DROP TABLE IF EXISTS `hero_game_mode_win`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_game_mode_win` (
  `hero_gamemode_win_id` int NOT NULL AUTO_INCREMENT,
  `hero_id` int NOT NULL,
  `game_mode_id` int NOT NULL COMMENT 'FK para game_mode',
  `win_rate` float NOT NULL,
  `date_of_the_data` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_gamemode_win_id`),
  UNIQUE KEY `uq_hero_gm_win_snapshot` (`hero_id`,`game_mode_id`,`date_of_the_data`),
  KEY `fk_hgw_gm` (`game_mode_id`),
  CONSTRAINT `fk_hgw_gm` FOREIGN KEY (`game_mode_id`) REFERENCES `game_mode` (`game_mode_id`),
  CONSTRAINT `fk_hgw_hero` FOREIGN KEY (`hero_id`) REFERENCES `hero` (`hero_id`)
) ENGINE=InnoDB AUTO_INCREMENT=265 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Histórico de Win Rate agregado por Herói e Modo de Jogo';
