  CONSTRAINT `fk_hrmw_map` FOREIGN KEY (`map_id`) REFERENCES `map` (`map_id`),
  CONSTRAINT `fk_hrmw_rank` FOREIGN KEY (`rank_id`) REFERENCES `rank` (`rank_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9549 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Histórico granular de Win Rate por Herói/Rank/Mapa';
