--
-- Table structure for table `hero_win`
--

DROP TABLE IF EXISTS `hero_win`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_win` (
  `hero_win_id` int NOT NULL AUTO_INCREMENT COMMENT 'Chave primária substituta',
  `hero_id` int NOT NULL COMMENT 'FK para hero',
  `win_rate` float NOT NULL COMMENT 'Métrica de Win Rate agregada por herói',
  `date_of_the_data` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Timestamp da inserção do snapshot',
  PRIMARY KEY (`hero_win_id`),
  UNIQUE KEY `uq_hero_win_snapshot` (`hero_id`,`date_of_the_data`),
  CONSTRAINT `fk_hw_hero` FOREIGN KEY (`hero_id`) REFERENCES `hero` (`hero_id`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Histórico de Win Rate agregado por Herói';
/*!40101 SET character_set_client = @saved_cs_client */;

